DATA = {
    "routes": ["X", "Y", "Z"],
    "cost_per_truck": {"X": 5, "Y": 4, "Z": 3},
    "upper_bound": {"X": 100, "Y": 120, "Z": 90},
    "xy_max": 200,       # trucks[X] + trucks[Y] <= 200
    "yz_min": 150,       # trucks[Y] + trucks[Z] >= 150
    "xz_diff": 30,       # trucks[X] - trucks[Z] == 30
}

