def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.routes = pyo.Set(initialize=d["routes"])

    def bound_rule(m, r):
        return (0, d["upper_bound"][r])

    model.trucks = pyo.Var(
        model.routes,
        domain=pyo.NonNegativeIntegers,
        bounds=bound_rule,
    )

    def obj_rule(m):
        return sum(d["cost_per_truck"][r] * m.trucks[r] for r in m.routes)

    model.obj = pyo.Objective(expr=obj_rule, sense=pyo.minimize)

    def xy_rule(m):
        return m.trucks["X"] + m.trucks["Y"] <= d["xy_max"]

    model.xy_capacity = pyo.Constraint(rule=xy_rule)

    def yz_rule(m):
        return m.trucks["Y"] + m.trucks["Z"] >= d["yz_min"]

    model.yz_coverage = pyo.Constraint(rule=yz_rule)

    def xz_rule(m):
        return m.trucks["X"] - m.trucks["Z"] == d["xz_diff"]

    model.xz_difference = pyo.Constraint(rule=xz_rule)

    return model

